import { NotificationBell } from '@refy-design/web';
import type { NotificationItem } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
const items: NotificationItem[] = [
  {
    id: 'n1',
    title: 'Review complete',
    description: 'refy.com.br: 84 pages, 12 critical.',
    time: '5 min ago',
    unread: true,
  },
  {
    id: 'n2',
    title: 'Project moved ahead 4 steps',
    description: 'Aurora project in the current cycle.',
    time: '2h ago',
    unread: true,
  },
  {
    id: 'n3',
    title: 'Credits running low',
    description: '300 credits left this cycle.',
    time: '1d ago',
    unread: true,
  },
  {
    id: 'n4',
    title: 'Invite accepted',
    description: 'Ana Costa joined the workspace.',
    time: '3d ago',
  },
  {
    id: 'n5',
    title: 'Weekly report available',
    description: 'Summary for June 12–18.',
    time: '5d ago',
  },
];
export function Example() {
  const args: Pick<ComponentProps<typeof NotificationBell>, 'items'> = { items };
  const [list, setList] = useState(items);
  return (
    <NotificationBell
      {...args}
      items={list}
      onItemClick={(item) =>
        setList((l) => l.map((n) => (n.id === item.id ? { ...n, unread: false } : n)))
      }
      onMarkAllRead={() => setList((l) => l.map((n) => ({ ...n, unread: false })))}
    />
  );
}

